import java.time.*;import java.time.temporal.ChronoUnit;
class Student { final String name; Student(String n){if(n==null||n.trim().isEmpty())throw new IllegalArgumentException();name=n;} }
abstract class Assignment { final String title;final int maxMarks;final LocalDate dueDate;Assignment(String t,int m,LocalDate d){if(t==null||t.trim().isEmpty()||m<=0||d==null)throw new IllegalArgumentException();title=t;maxMarks=m;dueDate=d;}abstract double applyPenalty(double marks,long days);}
class CodingAssignment extends Assignment { CodingAssignment(String t,int m,LocalDate d){super(t,m,d);}double applyPenalty(double x,long d){return Math.max(0,x*(1-.1*d));} }
class WrittenAssignment extends Assignment { WrittenAssignment(String t,int m,LocalDate d){super(t,m,d);}double applyPenalty(double x,long d){return Math.max(0,x*(1-.2*d));} }
class Submission { enum Status{SUBMITTED,GRADED}final Student student;final Assignment assignment;final LocalDate date;Status status=Status.SUBMITTED;Double marks;Submission(Student s,Assignment a,LocalDate d){if(s==null||a==null||d==null)throw new IllegalArgumentException();student=s;assignment=a;date=d;}long lateDays(){return Math.max(0,ChronoUnit.DAYS.between(assignment.dueDate,date));}double grade(double awarded){if(status==Status.GRADED)throw new IllegalStateException("Already graded");if(awarded<0||awarded>assignment.maxMarks)throw new IllegalArgumentException();marks=assignment.applyPenalty(awarded,lateDays());status=Status.GRADED;return marks;} }
public class Main {public static void main(String[]args){LocalDate mar10=LocalDate.of(2026,3,10),mar12=LocalDate.of(2026,3,12);Submission a=new Submission(new Student("Asha"),new CodingAssignment("Linked List Lab",50,mar10),mar10);Submission r=new Submission(new Student("Ravi"),new WrittenAssignment("Design Essay",50,mar12),LocalDate.of(2026,3,14));System.out.println(a.student.name+"'s submission for '"+a.assignment.title+"' received (on time). Status: "+a.status);System.out.println(r.student.name+"'s submission for '"+r.assignment.title+"' received ("+r.lateDays()+" days late). Status: "+r.status);System.out.println("Asha graded: "+a.grade(45)+"/50. Status: "+a.status);System.out.println("Ravi graded: "+r.grade(40)+"/50 after 40% late penalty. Status: "+r.status);try{a.grade(45);}catch(IllegalStateException e){System.out.println("Cannot resubmit: '"+a.assignment.title+"' has already been graded.");}}}